1	export interface Customer {
2	  yearsWithMHPCO: number;
3	}
4	
5	export interface Item {
6	  type: string;
7	  material?: string;
8	  enchantment?: number;
9	  cursed?: boolean;
10	}
11	
12	export interface QuoteStep {
13	  op: "quote";
14	  items: Item[];
15	}
16	
17	export interface Damage {
18	  itemType: string;
19	  amount: number;
20	}
21	
22	export interface Incident {
23	  cause: string;
24	  damages: Damage[];
25	}
26	
27	export interface ClaimStep {
28	  op: "claim";
29	  policy: number;
30	  incident: Incident;
31	}
32	
33	export type Step = QuoteStep | ClaimStep;
34	
35	export interface Scenario {
36	  customer: Customer;
37	  steps: Step[];
38	}
39	
40	export interface QuoteResult {
41	  premium: number;
42	}
43	
44	export interface ClaimResult {
45	  payout: number;
46	  remainingCap: number;
47	}
48	
49	export type StepResult = QuoteResult | ClaimResult;
50	
51	export interface ScenarioResult {
52	  results: StepResult[];
53	}
54	
55	// What MHPCO insures each item for, as distinct from what it charges to do so.
56	const INSURANCE_VALUES: Record<string, number> = {
57	  sword: 1000,
58	  amulet: 600,
59	  staff: 800,
60	  potion: 400,
61	  rune: 250,
62	  moonstone: 250,
63	};
64	
65	const BASE_PREMIUMS: Record<string, number> = {
66	  sword: 100,
67	  amulet: 60,
68	  staff: 80,
69	  potion: 40,
70	  rune: 25,
71	  moonstone: 25,
72	};
73	
74	// Percentages are applied as integer arithmetic (× percent ÷ 100) rather than
75	// as a float rate (× 1.1): this keeps intermediate values integral and avoids
76	// binary floating-point error — 100 * 1.1 is 110.00000000000001, but
77	// (100 * 110) / 100 is exact.
78	const ONE_HUNDRED_PERCENT = 100;
79	const FIRST_INSURANCE_SURCHARGE_PERCENT = 10;
80	const ADMIN_FEE = 5;
81	const LOYALTY_YEARS = 2;
82	const LOYALTY_DISCOUNT_PERCENT = 20;
83	const SUBSEQUENT_CONTRACT_DISCOUNT_PERCENT = 15;
84	const DEDUCTIBLE = 100;
85	const CAP_MULTIPLE = 2;
86	const NO_PAYOUT = 0;
87	const PERILOUS_ENCHANTMENT = 8;
88	const PERILOUS_ENCHANTMENT_REIMBURSEMENT_PERCENT = 50;
89	const FULL_REIMBURSEMENT_PERCENT = 100;
90	const DRAGON_MATERIAL = "dragon";
91	
92	const applyPercent = (amount: number, percent: number): number =>
93	  (amount * percent) / ONE_HUNDRED_PERCENT;
94	
95	const addSurcharge = (amount: number, surchargePercent: number): number =>
96	  applyPercent(amount, ONE_HUNDRED_PERCENT + surchargePercent);
97	
98	const applyDiscount = (amount: number, discountPercent: number): number =>
99	  applyPercent(amount, ONE_HUNDRED_PERCENT - discountPercent);
100	
101	const COMPONENT_TYPES = ["rune", "moonstone"];
102	const BUILDING_BLOCK_SIZE = 3;
103	const BUILDING_BLOCK_BASE_PREMIUM = 60;
104	const isComponent = (item: Item): boolean => COMPONENT_TYPES.includes(item.type);
105	
106	const basePremiumOf = (item: Item): number => BASE_PREMIUMS[item.type];
107	
108	// Risk surcharges are per-item properties of the insured object, each raising
109	// that item's premium by a percentage. They stack multiplicatively: an item
110	// matching two rules is surcharged by the first, then by the second.
111	interface RiskSurcharge {
112	  appliesTo: (item: Item) => boolean;
113	  percent: number;
114	}
115	
116	const HIGH_ENCHANTMENT = 5;
117	const NO_ENCHANTMENT = 0;
118	
119	const RISK_SURCHARGES: RiskSurcharge[] = [
120	  { appliesTo: (item) => item.cursed === true, percent: 50 },
121	  {
122	    appliesTo: (item) => (item.enchantment ?? NO_ENCHANTMENT) >= HIGH_ENCHANTMENT,
123	    percent: 30,
124	  },
125	];
126	
127	const riskAdjustedPremiumOf = (item: Item): number =>
128	  RISK_SURCHARGES.reduce(
129	    (premium, surcharge) =>
130	      surcharge.appliesTo(item) ? addSurcharge(premium, surcharge.percent) : premium,
131	    basePremiumOf(item),
132	  );
133	
134	const sumRiskAdjustedPremiums = (items: Item[]): number =>
135	  items.reduce((total, item) => total + riskAdjustedPremiumOf(item), 0);
136	
137	// Alike components are grouped into building blocks of 3, which carry a
138	// special base premium; the remaining components are priced individually,
139	// risk surcharges and all.
140	// Total over the empty group: no components means no blocks and no remainder.
141	const alikeComponentsPremium = (components: Item[]): number => {
142	  const blockCount = Math.floor(components.length / BUILDING_BLOCK_SIZE);
143	  const remainingComponents = components.slice(blockCount * BUILDING_BLOCK_SIZE);
144	  return (
145	    blockCount * BUILDING_BLOCK_BASE_PREMIUM +
146	    sumRiskAdjustedPremiums(remainingComponents)
147	  );
148	};
149	
150	// Splits items into those matching the predicate and those not, in one pass,
151	// so the rule dividing them is written exactly once.
152	const partition = (
153	  items: Item[],
154	  matches: (item: Item) => boolean,
155	): [Item[], Item[]] =>
156	  items.reduce<[Item[], Item[]]>(
157	    ([matching, rest], item) =>
158	      matches(item) ? [[...matching, item], rest] : [matching, [...rest, item]],
159	    [[], []],
160	  );
161	
162	const groupByType = (items: Item[]): Item[][] => [
163	  ...items
164	    .reduce(
165	      (groups, item) =>
166	        groups.set(item.type, [...(groups.get(item.type) ?? []), item]),
167	      new Map<string, Item[]>(),
168	    )
169	    .values(),
170	];
171	
172	// Components and main items are priced by different rules, so each group is
173	// totalled separately: components by building block, main items item by item.
174	const componentsPremium = (components: Item[]): number =>
175	  groupByType(components).reduce(
176	    (total, alike) => total + alikeComponentsPremium(alike),
177	    0,
178	  );
179	
180	// What the items alone cost to insure, before any modifier that depends on the
181	// customer or the contract they sit in. This is a premium, not a sum insured:
182	// what MHPCO *charges* for the cover, not what it will *pay out* — an amulet
183	// costs 60 here and is insured for 600 (see insuranceSumOf). Every item is
184	// either a component or a main item — the split is stated once, as a partition,
185	// so the two halves cannot drift apart — and each half is priced by its own
186	// rules.
187	const itemsPremiumOf = (items: Item[]): number => {
188	  const [components, mainItems] = partition(items, isComponent);
189	  return sumRiskAdjustedPremiums(mainItems) + componentsPremium(components);
190	};
191	
192	// Contract-level modifiers adjust the sum insured by the terms of the deal
193	// rather than the nature of the items. Like risk surcharges they stack
194	// multiplicatively, each applying to the result of the one before, so they are
195	// written the same way: a predicate over the contract, and an adjustment.
196	interface Contract {
197	  customer: Customer;
198	  isFirstContract: boolean;
199	}
200	
201	interface ContractModifier {
202	  appliesTo: (contract: Contract) => boolean;
203	  adjust: (amount: number) => number;
204	}
205	
206	// Every contract is priced on one of two standings: a first insurance is
207	// assessed a surcharge, a later one rewarded with a discount. This is a choice,
208	// not two independent rules, so it is written as one — there is no way to
209	// express a contract that gets both or neither.
210	const standingAdjustedPremiumOf = (
211	  amount: number,
212	  { isFirstContract }: Contract,
213	): number =>
214	  isFirstContract
215	    ? addSurcharge(amount, FIRST_INSURANCE_SURCHARGE_PERCENT)
216	    : applyDiscount(amount, SUBSEQUENT_CONTRACT_DISCOUNT_PERCENT);
217	
218	// Modifiers that a contract may or may not earn, on top of its standing. They
219	// stack multiplicatively, each applying to the result of the one before.
220	const CONTRACT_MODIFIERS: ContractModifier[] = [
221	  {
222	    appliesTo: ({ customer }) => customer.yearsWithMHPCO >= LOYALTY_YEARS,
223	    adjust: (amount) => applyDiscount(amount, LOYALTY_DISCOUNT_PERCENT),
224	  },
225	];
226	
227	const contractAdjustedPremiumOf = (
228	  itemsPremium: number,
229	  contract: Contract,
230	): number =>
231	  CONTRACT_MODIFIERS.reduce(
232	    (premium, modifier) =>
233	      modifier.appliesTo(contract) ? modifier.adjust(premium) : premium,
234	    standingAdjustedPremiumOf(itemsPremium, contract),
235	  );
236	
237	// Premiums round up in MHPCO's favour, and the flat admin fee is added last
238	// so that no percentage ever applies to it.
239	const billedPremiumOf = (premium: number): number =>
240	  Math.ceil(premium) + ADMIN_FEE;
241	
242	const quote = (step: QuoteStep, contract: Contract): QuoteResult => ({
243	  premium: billedPremiumOf(
244	    contractAdjustedPremiumOf(itemsPremiumOf(step.items), contract),
245	  ),
246	});
247	
248	// The insurance sum is what the items are covered for, and it is the basis of
249	// the payout cap — unrelated to the premium charged for that cover.
250	const insuranceSumOf = (items: Item[]): number =>
251	  items.reduce((total, item) => total + INSURANCE_VALUES[item.type], 0);
252	
253	// A quote creates a policy, which then absorbs claims: every payout draws down
254	// a cap of twice the insurance sum, so the policy carries state between steps.
255	// The policy keeps the items it covers: a claim is settled by the nature of the
256	// damaged item, so the cover has to be able to look back at what it insured.
257	interface Policy {
258	  remainingCap: number;
259	  items: Item[];
260	}
261	
262	const policyFor = (items: Item[]): Policy => ({
263	  remainingCap: insuranceSumOf(items) * CAP_MULTIPLE,
264	  items,
265	});
266	
267	// How much of a damage MHPCO shoulders depends on what was damaged: an item so
268	// heavily enchanted that its own magic invites disaster is met halfway. Unlike
269	// the risk surcharges, these rules select rather than stack — an item is
270	// settled on one footing, so the first matching rule decides and the rest are
271	// not consulted. Precedence is therefore the order of this list.
272	interface ReimbursementRule {
273	  appliesTo: (item: Item) => boolean;
274	  percent: number;
275	}
276	
277	const REIMBURSEMENT_RULES: ReimbursementRule[] = [
278	  // Dragon stuff is made whole however perilously enchanted it also is, so this
279	  // rule is listed first and the perilous-enchantment rule never gets to speak.
280	  {
281	    appliesTo: (item) => item.material === DRAGON_MATERIAL,
282	    percent: FULL_REIMBURSEMENT_PERCENT,
283	  },
284	  {
285	    appliesTo: (item) =>
286	      (item.enchantment ?? NO_ENCHANTMENT) >= PERILOUS_ENCHANTMENT,
287	    percent: PERILOUS_ENCHANTMENT_REIMBURSEMENT_PERCENT,
288	  },
289	];
290	
291	// A damage names a type, and a policy may insure several items of that type, so
292	// a rule speaks for the damage if it applies to any of them.
293	const governs = (rule: ReimbursementRule, damagedItems: Item[]): boolean =>
294	  damagedItems.some(rule.appliesTo);
295	
296	// No rule matching means nothing about the item argues for paying less than in
297	// full. An item MHPCO has no record of insuring matches no rule either, and so
298	// is reimbursed in full by the same default.
299	const reimbursementPercentFor = (damagedItems: Item[]): number =>
300	  REIMBURSEMENT_RULES.find((rule) => governs(rule, damagedItems))?.percent ??
301	  FULL_REIMBURSEMENT_PERCENT;
302	
303	// A damage names an item type; the policy knows what it insured under that
304	// name, and the item's nature decides how much of the loss is met.
305	const insuredItemsOfType = (policy: Policy, itemType: string): Item[] =>
306	  policy.items.filter((item) => item.type === itemType);
307	
308	const reimbursementFor = (damage: Damage, policy: Policy): number =>
309	  applyPercent(
310	    damage.amount,
311	    reimbursementPercentFor(insuredItemsOfType(policy, damage.itemType)),
312	  );
313	
314	// An incident's damages are reimbursed one by one, then totalled before the
315	// deductible is taken, so the deductible falls once on the event rather than
316	// once per damaged item.
317	const reimbursementTotalOf = (incident: Incident, policy: Policy): number =>
318	  incident.damages.reduce(
319	    (total, damage) => total + reimbursementFor(damage, policy),
320	    0,
321	  );
322	
323	// The deductible reduces the payout, it never turns it into a charge: a loss
324	// smaller than the deductible is simply not paid, rather than billed back.
325	const netOfDeductible = (reimbursement: number): number =>
326	  Math.max(reimbursement - DEDUCTIBLE, NO_PAYOUT);
327	
328	// However great the loss, a policy pays out only what it has left to give, and
329	// a payout draws the cap down by exactly what was paid.
330	const payableUnder = (policy: Policy, reimbursement: number): number =>
331	  Math.min(netOfDeductible(reimbursement), policy.remainingCap);
332	
333	const claim = (step: ClaimStep, policy: Policy): ClaimResult => {
334	  const payout = payableUnder(
335	    policy,
336	    reimbursementTotalOf(step.incident, policy),
337	  );
338	  return { payout, remainingCap: policy.remainingCap - payout };
339	};
340	
341	// Steps are processed in order because each one depends on what came before: a
342	// quote's standing depends on how many contracts precede it, and a claim draws
343	// down the cap its policy has left. Both are carried explicitly as the policies
344	// map rather than mutated in place, so a step's effect on later steps is
345	// visible in what it returns.
346	interface Ledger {
347	  policies: Map<number, Policy>;
348	  results: StepResult[];
349	}
350	
351	const withPolicy = (
352	  policies: Map<number, Policy>,
353	  policyNumber: number,
354	  policy: Policy,
355	): Map<number, Policy> => new Map(policies).set(policyNumber, policy);
356	
357	// Every step settles the same way: it produces one result, and it leaves the
358	// policies it touched in whatever state that result implies. Saying so once
359	// keeps the two kinds of step from drifting apart in how they are recorded.
360	interface Settlement {
361	  policies: Map<number, Policy>;
362	  result: StepResult;
363	}
364	
365	// A quote opens a policy, numbered by its own position in the scenario — that
366	// number is what a later claim names to draw on this cover.
367	const settleQuote = (
368	  policies: Map<number, Policy>,
369	  step: QuoteStep,
370	  policyNumber: number,
371	  customer: Customer,
372	): Settlement => ({
373	  policies: withPolicy(policies, policyNumber, policyFor(step.items)),
374	  result: quote(step, { customer, isFirstContract: policyNumber === 0 }),
375	});
376	
377	const policyNamedBy = (
378	  policies: Map<number, Policy>,
379	  step: ClaimStep,
380	): Policy => {
381	  const policy = policies.get(step.policy);
382	  if (policy === undefined) {
383	    throw new Error(`Claim refers to unknown policy ${step.policy}`);
384	  }
385	  return policy;
386	};
387	
388	// A claim draws the named policy's cap down by what it paid, and writes the
389	// drawn-down policy back so the next claim on it sees the smaller cap.
390	const settleClaim = (
391	  policies: Map<number, Policy>,
392	  step: ClaimStep,
393	): Settlement => {
394	  const policy = policyNamedBy(policies, step);
395	  const result = claim(step, policy);
396	  return {
397	    policies: withPolicy(policies, step.policy, {
398	      ...policy,
399	      remainingCap: result.remainingCap,
400	    }),
401	    result,
402	  };
403	};
404	
405	const applyStep = (
406	  { policies, results }: Ledger,
407	  step: Step,
408	  index: number,
409	  customer: Customer,
410	): Ledger => {
411	  const settlement =
412	    step.op === "quote"
413	      ? settleQuote(policies, step, index, customer)
414	      : settleClaim(policies, step);
415	  return {
416	    policies: settlement.policies,
417	    results: [...results, settlement.result],
418	  };
419	};
420	
421	export const runScenario = ({ customer, steps }: Scenario): ScenarioResult => {
422	  const { results } = steps.reduce<Ledger>(
423	    (ledger, step, index) => applyStep(ledger, step, index, customer),
424	    { policies: new Map(), results: [] },
425	  );
426	  return { results };
427	};
